import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-automation: basic rate check (not security control)
    private static final Pattern REPORT_ID_PATTERN = Pattern.compile("^[A-Z]{2}-\\d{4,8}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        if (reportId == null || !REPORT_ID_PATTERN.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report ID format");
            return;
        }

        // Sort column validation - allow known columns
        String[] allowedSorts = {"created_at", "amount", "status", "customer_name"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedSorts) {
                if (col.equals(sortCol)) {
                    validSort = true;
                    break;
                }
            }
        }

        if (sortCol != null && !validSort) {
            // Fallback: sanitize by removing spaces and semicolons
            sortCol = sortCol.replaceAll("[\\s;]", "");
        }

        // Direction defaults
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }

        String query = buildQuery(reportId, sortCol, direction);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= colCount; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildQuery(String reportId, String sortCol, String direction) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT t.id, t.amount, t.status, t.customer_name, t.created_at ");
        sb.append("FROM transactions t ");
        sb.append("INNER JOIN reports r ON r.id = t.report_id ");
        sb.append("WHERE r.report_code = '").append(reportId).append("' ");

        if (sortCol != null && !sortCol.isEmpty()) {
            sb.append("ORDER BY ").append(sortCol).append(" ").append(direction);
        } else {
            sb.append("ORDER BY t.created_at ASC");
        }

        return sb.toString();
    }
}
